/* Debris update: falls and spins, bounces off what it hits with a random kick, bursts into 40 sparks once it comes to rest (or its unk10 timer runs out), or fades out over unk28 frames when unk20 is set.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/entities/002f6328.c, FUN_L01_002f8718. */
void rock_update(struct Moby *m) {
    DebrisVars_2f8530 *d = (DebrisVars_2f8530 *)m->pvars;
    Vec4 old;
    Vec4 v;
    Vec4 p;
    Vec4 t;
    f32 ang;
    f32 spin;
    s32 i;

    qcopy(&old, &m->pos);
    d->vel.z -= d->gravity;
    FastVecAdd(&m->pos, &m->pos, &d->vel);
    m->rot.z = FastAddRots(m->rot.z, d->spin);
    if (m->pos.x < 2.0f || 1021.0f < m->pos.x || m->pos.y < 2.0f || 1021.0f < m->pos.y || m->pos.z < 2.0f ||
        1021.0f < m->pos.z) {
        DeleteMoby(m);
        return;
    }
    if (fast_dec_timer(&d->life)) {
        if (coll_line(&old, &m->pos, 0, m, 0) != 0 || coll_sphere(d->scale, &m->pos, 0, m) != 0) {
            ang = fast_atan2(d->vel.x, d->vel.y);
            v.f[0] = FastCos(FastAddRots(ang, random_float_between(-3.1415927f, 3.1415927f))) *
                     random_float_between(0.0f, d->vel.z * 0.35f);
            v.f[1] = FastSin(FastAddRots(ang, random_float_between(-3.1415927f, 3.1415927f))) *
                     random_float_between(0.0f, d->vel.z * 0.35f);
            v.f[2] = 0.0f;
            m->rot.x = random_float_between(-3.1415927f, 3.1415927f);
            m->rot.y = random_float_between(-3.1415927f, 3.1415927f);
            m->rot.z = random_float_between(-3.1415927f, 3.1415927f);
            vec_reflect(&d->vel, &d->vel, &novalis_coll_hit.normal_x);
            FastVecScale(&d->vel, &d->vel, random_float_between(0.07f, 0.13f));
            FastVecAdd(&d->vel, &d->vel, &v);
            vec_scale_to_length(&novalis_coll_hit.normal_x, &novalis_coll_hit.normal_x, 0.1f);
            FastVecAdd(&m->pos, &novalis_coll_hit.normal_x, &novalis_coll_hit.point);
            spin = random_float_between(g_frame_time * 1.5707964f, g_frame_time * 6.2831855f);
            if (0.0f < d->spin) {
                spin = -spin;
            }
            d->spin = spin;
        }
    }
    if (d->unk20 == 0) {
        if (fast_dec_timer(&d->unk10) == 0) {
            if (!(FastVecLength(&d->vel) < g_frame_time * 0.5f)) {
                return;
            }
            if (d->life != 0) {
                return;
            }
        }
        for (i = 0; i < 40; i++) {
            p.q = 0;
            p.f[0] = random_float_between(-1.0f, 1.0f);
            p.f[1] = random_float_between(-1.0f, 1.0f);
            p.f[2] = random_float_between(-1.0f, 1.0f);
            t.q = 0;
            v.q = p.q;
            t.f[0] = random_float_between(-1.0f, 1.0f);
            t.f[1] = random_float_between(-1.0f, 1.0f);
            t.f[2] = random_float_between(-1.0f, 1.0f);
            p.q = t.q;
            vec_scale_to_length(&p, &p, random_float_between(0.0f, 0.5f));
            FastVecAdd(&p, &p, &m->pos);
            vec_scale_to_length(&v, &v, random_float_between(0.0f, 0.5f) * g_frame_time);
            FastVecAdd(&v, &v, &d->vel);
            spawn_effect_particle_with_target_scalar(&p, &v, 0x1F0C1820, 0x81020, random_float_between(70000.0f, 140000.0f),
                             scale_ticks(rand_range(20, 60)));
        }
        DeleteMoby(m);
    } else if (fast_dec_timer(&d->unk10) != 0) {
        DeleteMoby(m);
    } else {
        m->alpha = d->unk10 * 127 / d->unk28;
    }
}
