/* Draws the visibomb's tiled screen overlay when outside its zone. */
void draw_visibomb_outside_zone_overlay(char *moby) {
    int *vars = ((int *)((Moby *)moby)->pvars);
    int row_count;
    int column_count;
    int row;
    int column;
    float screen_center[2];
    volatile float coordinate[2];
    float opacity;
    int color;
    int texture_x;
    int texture_y;
    int draw_x;
    int draw_y;
    int tile_size = 32;
    int tile_half;
    long texture;

    screen_center[0] = IntToFloat(g_screen_extent.half_width);
    screen_center[1] = IntToFloat(g_screen_extent.half_height);
    texture = GetEffectTex(30);
    row_count = g_screen_extent.width / 32 + 1;
    column_count = g_screen_extent.height / 32 + 1;
    for (row = 0; row < row_count; row++) {
        int base_color = 0xff7f7f;
        for (column = 0; column < column_count; column++) {
            coordinate[0] = (float)(row * 32);
            coordinate[1] = (float)(column * 32);
            tile_half = tile_size >> 1;
            opacity = IntToFloat(vars[0x50]) * 127.5f / IntToFloat(scale_ticks(90));
            color = (truncate_float_to_s32(opacity) << 24) + base_color;
            texture_x = random_integer_below(32);
            texture_y = random_integer_below(32);
            draw_x = truncate_float_to_s32(coordinate[0] - (float)tile_half);
            draw_y = truncate_float_to_s32(coordinate[1] - (float)tile_half);
            DrawTexturedQuad(draw_x, draw_y, 32, 32, texture_x, texture_y, 32, 32, color, texture);
        }
    }
}
