        o->pos.z += *(float *)&teleporter_child_height_offset;
        *(float *)(*p + 0x44) = u;
        t = d->open_a * 2.4f - 1.2f;
        euler_rotation_basis(*p + 0xC0, *p + 0x40);
        vec_scale_to_length(v, *p + 0xC0, t);
        FastVecAdd(*p + 0x10, *p + 0x10, v);
        *(float *)(*p + 0x44) = d->open_b * -1.0471976f - 0.34906584f;
        euler_rotation_basis(*p + 0xC0, *p + 0x40);
