/* Resets the camera's orbit, focus, spring, view and track from fixed values; for a kind 2 preset it also prepares its two paths once, measuring each point against the path it follows.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/vendor/0030b618.c, FUN_L01_00314e98. */
void reset_camera_state_and_prepare_preset_paths(Camera *cam) {
    Vec4 at;
    s32 seg;
    f32 t;
    CameraPreset *s = novalis_camera_descriptors_r[cam->preset].preset;
    CameraControl *control;
    CameraFocus *focus;
    CameraSpring *spring;
    CameraOrbit *orbit;
    CameraView *view;
    CameraTrack *track;
    CameraBlend *blend;
    CameraPath *a, *b, *c, *d;
    s32 i, j, k, n, prev;

    focus = &cam->orbit->focus;
    focus->dist = 1.5f;
    focus->state = 0;
    if (s->kind == 3) {
        focus->dist = 0.5f;
    }
    control = &cam->control;
    focus->max_angle = 0.20943952f;
    spring = &cam->orbit->spring;
    spring->dist = 6.0f;
    spring->unk4 = 0.5f;
    spring->height = 2.0f;
    orbit = cam->orbit;
    orbit->unk10 = 0.01f;
    orbit->unk14 = 0.175f;
    orbit->unk18 = 0;
    orbit->mode = 0;
    orbit->unk20 = 0.0005f;
    orbit->unk24 = 0;
    clear_u64_value(orbit);
    view = &cam->orbit->view;
    view->unk20 = 0.01f;
    view->unk24 = 0.3f;
    view->unk28 = 0.2f;
    view->unk2C = 0;
    clear_u64_value(view);
    track = &cam->orbit->track;
    clear_u64_value(track);
    clear_u64_value(&track->accel);
    track->unk40 = 3.0f;
    track->unk30 = 0.003f;
    track->unk34 = 0.1f;
    track->unk38 = 0.2f;
    track->unk3C = 0;
    blend = &cam->orbit->blend;
    blend->unk0 = 0;
    blend->unk4 = 0;
    blend->unk8 = 0;
    blend->unkC = 0;
    blend->unk10 = 1;
    if (s->kind == 2 && s->ready == 0) {
        b = novalis_paths_r2[s->track_path];
        d = novalis_rails_r[s->target].path;
        a = novalis_paths_r2[s->path];
        c = novalis_paths_r2[s->look_path];
        s->ready = 1;
        for (i = 0; i < a->count; i++) {
            find_nearest_path_point(b, &a->pts[i], &at, &seg, &t, 0, 20.0f, 5.0f, 0.0f);
            a->pts[i].f[0] = a->pts[i].f[3];
            a->pts[i].f[3] = seg;
        }
        prev = a->count - 1;
        for (i = 0; i < a->count; i++) {
            j = truncate_float_to_s32(a->pts[prev].f[3]);
            n = truncate_float_to_s32(a->pts[i].f[3]) - j;
            if (n < 0) {
                n += b->count;
            }
            t = 0.0f;
            for (k = 0; k < n; k++) {
                t += b->pts[(j + i) % b->count].f[3];
            }
            a->pts[i].f[1] = t;
            prev = i;
        }
        for (i = 0; i < c->count; i++) {
            find_nearest_path_point(d, &c->pts[i], &at, &seg, &t, 0, 20.0f, 5.0f, 0.0f);
            c->pts[i].f[0] = c->pts[i].f[3];
            c->pts[i].f[3] = seg;
        }
        prev = c->count - 1;
        for (i = 0; i < c->count; i++) {
            j = truncate_float_to_s32(c->pts[prev].f[3]);
            n = truncate_float_to_s32(c->pts[i].f[3]) - j;
            if (n < 0) {
                n += d->count;
            }
            t = 0.0f;
            for (k = 0; k < n; k++) {
                t += d->pts[(j + i) % d->count].f[3];
            }
            c->pts[i].f[1] = t;
            prev = i;
        }
    }
    control->mode = 0;
}
