        seg = ((Hero *)(hero_globals_base + 0xE1D))->rail_segment;
        frac = ((Hero *)(hero_globals_base + 0xE1D))->rail_seg_frac;
        c->t = frac;
        c->idx = seg;
        Spline_AdvanceByDistance(novalis_paths_r3[pi], v0, &c->idx, &c->t, 1.0f, 0);
